const APP_HOOKS={
  afterLanguage:[],beforeOpenParticipant:[],afterOpenParticipant:[],afterCloseParticipant:[],afterToggleAcc:[],beforeImgZoom:[],afterImgZoom:[],transformExportHtml:[]
};
function runAppHooks(list){const args=[].slice.call(arguments,1);list.forEach(function(fn){try{fn.apply(null,args);}catch(err){console.error('hook error',err);}});}
function runTransformHooks(list,value){const args=[].slice.call(arguments,2);return list.reduce(function(v,fn){try{return fn.apply(null,[v].concat(args));}catch(err){console.error('transform hook error',err);return v;}},value);}


