const ECO_GUIDE_PREFIX = {e1:'g-daria', e2:'g-lectorium', e3:'g-versailles-events', e4:'g-khvost', e5:'g-russian-teacher', e6:'g-gymnasium', e7:'g-pariskids', e8:'g-zvezdochki'};
