    PC_SEED.e8 = PC_SEED.e8 || {};
    PC_SEED.e8.bio = {"fr": "Dasha. Directrice du projet du camp de jour pour enfants « Nashi Zvezdochki » à Cergy.", "en": "Dasha. Project director of the Nashi Zvezdochki children's day camp in Cergy.", "ru": "Даша. Руководитель проекта детского дневного лагеря «Наши звёздочки» в Cergy."};
    PC_SEED.e8.html = PC_SEED.e8.html || {fr:'',en:'',ru:''};
