function renderEco(L){
  const data=BAKED_DATA.eco[L]||BAKED_DATA.eco.fr;
  Object.keys(data).forEach(function(id){
    const d=data[id]; const row=document.querySelector('[data-eco-row="'+id+'"]');
    if(row){const cells=row.querySelectorAll('td'); if(cells[1])cells[1].textContent=d[0]; if(cells[2])cells[2].innerHTML='<span class="tg tg-eco">'+d[1]+'</span>'; if(cells[3])cells[3].textContent=d[2];}
    const card=document.querySelector('#p3-fiches .pcard[data-num="'+id+'"]');
    if(card){card.dataset.name=d[0]; const nm=card.querySelector('.pcard-name'); if(nm)nm.textContent=d[0]; const tg=card.querySelector('.tg'); if(tg){tg.removeAttribute('data-i18n');tg.textContent=d[3];}}
  });
  const e5=document.querySelector('[data-eco-row="e5"] .rec-d'); if(e5)e5.textContent='17.08.26';
}

function renderQTable(L){
  const table=document.querySelector('.research-trace-table'); if(!table)return;
  const d=BAKED_DATA.qtable[L]||BAKED_DATA.qtable.fr;
  table.innerHTML='<thead><tr>'+d.heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+d.qs.map(q=>'<tr><td><strong>'+q[0]+'</strong></td>'+q[1].map(v=>'<td class="method-dot">'+(v?'●':'')+'</td>').join('')+'<td>'+q[2]+'</td></tr>').join('')+'</tbody>';
  if(!table.parentElement.classList.contains('baked-method-wrap')){const w=document.createElement('div');w.className='baked-method-wrap';table.parentNode.insertBefore(w,table);w.appendChild(table);}
}

function renderFocus(L){
  const f=BAKED_DATA.focus[L]||BAKED_DATA.focus.fr;
  document.querySelectorAll('[data-i18n="flow-29-title"],[data-i18n="s4-1-5-title"]').forEach(function(e){e.textContent=f.title;});
  const box=document.querySelector('#flow-29 .focus-persona'); if(!box)return;
  box.innerHTML='<div class="focus-rationale"><p>'+f.main+'</p></div><p>'+f.secondary+'</p><div class="focus-roles"><div class="focus-role primary"><strong>'+f.p+'</strong><span>'+f.main+'</span></div><div class="focus-role"><strong>'+f.s+'</strong><span>'+f.secondary+'</span></div></div>';
  const prev=document.querySelector('#flow-29') && document.querySelector('#flow-29').previousElementSibling;
  if(prev && /^(Conclusions?|Выводы|Conclusions?)$/i.test((prev.textContent||'').trim())) prev.remove();
}

function insertSurveyN(L){
  let p=document.getElementById('surveyNMax');
  if(!p){p=document.createElement('p');p.id='surveyNMax';p.className='survey-n-max';const a=document.getElementById('s3-1-1');if(a)a.insertAdjacentElement('afterend',p);}
  if(p)p.textContent=(L==='en'?'max n = 32':'n max = 32');
}

function removeWater(){
  // Bibliography navigation only; source traceability can remain elsewhere.
  document.querySelectorAll('.nav-bibliography-details').forEach(e=>e.remove());
  // Removed obsolete project-presentation heading/menu.
  document.querySelectorAll('[data-i18n="flow-36-title"],[data-i18n="s4-4-1-title"]').forEach(function(e){const a=e.closest('a'); if(a)a.remove(); else e.remove();});
  // Remove research-outcome disclaimer block (2nd h4 + following paragraph in flow-06).
  const flow=document.getElementById('flow-06'); if(flow){const hs=flow.querySelectorAll('h4'); if(hs.length>=2){const h=hs[1];const p=h.nextElementSibling;if(p&&p.tagName==='P')p.remove();h.remove();}}
  document.querySelectorAll('[data-i18n="note-bench"]').forEach(e=>e.remove());
}

function ensureHypModal(){
  if(document.getElementById('bakedHypModal'))return;
  const m=document.createElement('div');m.id='bakedHypModal';m.className='baked-hyp-modal';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');m.innerHTML='<div class="baked-hyp-card"><button class="baked-hyp-close" type="button" aria-label="Close">×</button><h3 id="bakedHypTitle"></h3><p id="bakedHypBody"></p></div>';document.body.appendChild(m);
  m.addEventListener('click',e=>{if(e.target===m||e.target.classList.contains('baked-hyp-close'))m.classList.remove('open');});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')m.classList.remove('open');});
  document.addEventListener('click',function(e){const chip=e.target.closest('.learning-hypotheses .hyp-mini');if(!chip)return;const hit=(chip.textContent||'').match(/H([1-4])/i);if(!hit)return;const n=hit[1],L=lang();let title='H'+n,body='';try{title=(translations[L]['hyp-h'+n+'-t']||title);body=(translations[L]['hyp-h'+n+'-b']||'');}catch(err){};document.getElementById('bakedHypTitle').innerHTML='H'+n+' · '+title;document.getElementById('bakedHypBody').innerHTML=body;m.classList.add('open');});
  document.querySelectorAll('.learning-hypotheses .hyp-mini').forEach(function(x){x.setAttribute('role','button');x.setAttribute('tabindex','0');x.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();x.click();}});});
}

function applyCanonicalCorrections(){
  const L=lang();
  renderEco(L); renderQTable(L); renderFocus(L); insertSurveyN(L); removeWater(); ensureHypModal();
  const __hc=document.querySelector('#bakedHypModal .baked-hyp-close'); if(__hc)__hc.setAttribute('aria-label',L==='ru'?'Закрыть':(L==='en'?'Close':'Fermer'));
  // BAKED corpus reconciliation for the two rows corrected from canonical transcripts.
  const prow=[...document.querySelectorAll('#p2-recrutement table.rec-table tbody tr')];
  const jr=prow.find(r=>r.querySelector('.rec-nom')&&r.querySelector('.rec-nom').textContent.trim()==='Julia K.'); if(jr){const c=jr.querySelectorAll('td');if(c[4])c[4].innerHTML='<span class="yn yn-y">'+(L==='fr'?'oui':L==='ru'?'да':'yes')+'</span>';if(c[10])c[10].innerHTML='<span class="tg tg-in">'+(L==='fr'?'dans le milieu':L==='ru'?'в среде':'within the network')+'</span>';if(c[11])c[11].innerHTML='<span class="yn yn-y">'+(L==='fr'?'oui':L==='ru'?'да':'yes')+'</span>';}
  const kr=prow.find(r=>r.querySelector('.rec-nom')&&r.querySelector('.rec-nom').textContent.trim()==='Katya P.'); if(kr){const c=kr.querySelectorAll('td');if(c[4])c[4].innerHTML='<span class="yn yn-y">'+(L==='fr'?'oui':L==='ru'?'да':'yes')+'</span>';if(c[8])c[8].innerHTML=(translations[L]&&translations[L]['p15-act'])||'';if(c[12])c[12].innerHTML='<span class="st st-done">'+(L==='fr'?'réalisé':L==='ru'?'проведено':'completed')+'</span><span class="rec-d">07.08.26</span>';}
  const q1=document.querySelector('[data-i18n="rec-q1-n"]'); if(q1)q1.innerHTML='16 <span>/ 20 · 80 %</span>'; const q3=document.querySelector('[data-i18n="rec-q3-n"]'); if(q3)q3.innerHTML='12 <span>/ 20 · 60 %</span>';
  const pmS=(translations[L]&&translations[L]['persona-match-sacha'])||'';document.querySelectorAll('[data-i18n="persona-match-sacha"]').forEach(e=>e.textContent=pmS); const pmV=(translations[L]&&translations[L]['persona-match-victor'])||'';document.querySelectorAll('[data-i18n="persona-match-victor"]').forEach(e=>e.textContent=pmV);
  // Canonical persona tags on the 20 parent cards.
  const personaMap={1:'NINA',2:'NINA',3:'ANYA',4:'SACHA',5:'SACHA',6:'NINA',7:'VICTOR',8:'ANYA',9:'SACHA',10:'VICTOR',11:'ANTI',12:'ANYA',13:'ANYA',14:'VICTOR',15:'SACHA',16:'NINA',17:'SACHA',18:'VICTOR',19:'ANYA',20:'SACHA'};
  document.querySelectorAll('#pc-grid-anchor .pcard[data-num]').forEach(function(card){const n=Number(card.dataset.num),v=personaMap[n];if(!v)return;let tags=card.querySelector('.pcard-tags');if(!tags)return;let old=tags.querySelector('.tg-persona');if(old)old.remove();const tg=document.createElement('span');tg.className='tg tg-persona '+(v==='ANTI'?'tg-persona-anti':'tg-persona-'+v.toLowerCase());const names={fr:{NINA:'PERSONA: NINA',ANYA:'PERSONA: ANYA',SACHA:'PERSONA: SACHA',VICTOR:'PERSONA: VICTOR',ANTI:'ANTI-PERSONA: OLGA'},en:{NINA:'PERSONA: NINA',ANYA:'PERSONA: ANYA',SACHA:'PERSONA: SACHA',VICTOR:'PERSONA: VICTOR',ANTI:'ANTI-PERSONA: OLGA'},ru:{NINA:'ПЕРСОНА: НИНА',ANYA:'ПЕРСОНА: АНЯ',SACHA:'ПЕРСОНА: САША',VICTOR:'ПЕРСОНА: ВИКТОР',ANTI:'АНТИ-ПЕРСОНА: ОЛЬГА'}};tg.textContent=names[L][v];tags.appendChild(tg);});
  const p20=document.querySelector('#pc-grid-anchor .pcard[data-num="20"]');if(p20){const strong=[...p20.querySelectorAll('.pcard-list li')].find(x=>/Citations fortes|Strong quotes|Сильные цитаты/i.test(x.textContent||''));if(strong)strong.classList.add('done');}
  // guarantee all parent quota cards use same green state; baked quota values stay authoritative.
  document.querySelectorAll('#p2-quotas-parents + p + .quota-grid .quota').forEach(function(q){q.classList.remove('quota-miss');q.classList.add('quota-met','quota-ok');});
  // update ch7 topbar remnants if any.
  document.querySelectorAll('[data-i18n="ch7-title"]').forEach(e=>e.textContent=BAKED_DATA.chapter[L].ch7);
  // Ecosystem count is 7 completed out of 9 targeted after adding Shaltai-Boltai.
  const ecoStat=document.querySelector('#p3-recrutement .rec-stat'); if(ecoStat){const bs=ecoStat.querySelectorAll('b');if(bs[0])bs[0].textContent='7';if(bs[1])bs[1].textContent='78 %';}
}

